/**
 * In-memory key-value store.
 */
const data = new Map<string, string>();

export function set(key: string, value: string): void {
  data.set(key, value);
}

export function get(key: string): string | undefined {
  return data.get(key);
}

export function del(key: string): boolean {
  return data.delete(key);
}

import { createServer } from "node:http";
import { get, set, del } from "./store.ts";

const port = Number(process.env.PORT ?? 3000);

function json(res: import("node:http").ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { "content-type": "application/json" });
  res.end(JSON.stringify(body));
}

async function readBody(req: import("node:http").IncomingMessage): Promise<string> {
  let body = "";
  for await (const chunk of req) body += chunk;
  return body;
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url ?? "/", `http://${req.headers.host ?? "localhost"}`);
  const match = url.pathname.match(/^\/kv\/([^/]+)$/);

  if (!match) {
    json(res, 404, { error: "not found" });
    return;
  }
  const key = decodeURIComponent(match[1]);

  switch (req.method) {
    case "GET": {
      const value = get(key);
      if (value === undefined) {
        json(res, 404, { error: "key not found", key });
      } else {
        json(res, 200, { key, value });
      }
      return;
    }
    case "PUT": {
      const body = await readBody(req);
      set(key, body);
      json(res, 200, { ok: true, key });
      return;
    }
    case "DELETE": {
      const deleted = del(key);
      if (deleted) {
        json(res, 200, { ok: true, key });
      } else {
        json(res, 404, { error: "key not found", key });
      }
      return;
    }
    default:
      json(res, 405, { error: "method not allowed" });
  }
});

server.listen(port, () => {
  console.log(`kv store listening on http://localhost:${port}`);
});

import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { set, get, del } from "../src/store.ts";

beforeEach(() => {
  // reset state between tests by deleting known keys
  for (const k of ["a", "b"]) del(k);
});

test("set then get returns the value", () => {
  set("a", "1");
  assert.equal(get("a"), "1");
});

test("get of missing key returns undefined", () => {
  assert.equal(get("missing"), undefined);
});

test("set overwrites existing value", () => {
  set("a", "1");
  set("a", "2");
  assert.equal(get("a"), "2");
});

test("del removes key and returns true", () => {
  set("a", "1");
  assert.equal(del("a"), true);
  assert.equal(get("a"), undefined);
});

test("del of missing key returns false", () => {
  assert.equal(del("nope"), false);
});

import { test, before, after } from "node:test";
import assert from "node:assert/strict";
import { createServer, type Server } from "node:http";
import { del } from "../src/store.ts";
import { handler } from "../src/server.ts";

let server: Server;
let base: string;

before(async () => {
  server = createServer(handler);
  await new Promise<void>((resolve) => server.listen(0, resolve));
  const addr = server.address();
  if (typeof addr !== "object" || addr === null) throw new Error("no address");
  base = `http://localhost:${addr.port}`;
});

after(() => server.close());

test("PUT then GET round-trips a value", async () => {
  del("k1");
  const put = await fetch(`${base}/kv/k1`, { method: "PUT", body: "hello" });
  assert.equal(put.status, 200);

  const res = await fetch(`${base}/kv/k1`);
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { key: "k1", value: "hello" });
});

test("GET of missing key returns 404", async () => {
  del("absent");
  const res = await fetch(`${base}/kv/absent`);
  assert.equal(res.status, 404);
});

test("DELETE removes a key, second DELETE is 404", async () => {
  del("k2");
  await fetch(`${base}/kv/k2`, { method: "PUT", body: "x" });

  const d1 = await fetch(`${base}/kv/k2`, { method: "DELETE" });
  assert.equal(d1.status, 200);

  const d2 = await fetch(`${base}/kv/k2`, { method: "DELETE" });
  assert.equal(d2.status, 404);
});

test("unknown path returns 404", async () => {
  const res = await fetch(`${base}/other`);
  assert.equal(res.status, 404);
});

test("unsupported method returns 405", async () => {
  const res = await fetch(`${base}/kv/k3`, { method: "PATCH" });
  assert.equal(res.status, 405);
});

