import { test } from "node:test";
import assert from "node:assert/strict";
import { execFile } from "node:child_process";
import { fileURLToPath } from "node:url";

const serverPath = fileURLToPath(new URL("../src/server.ts", import.meta.url));

function runServer(envPatch: Record<string, string | undefined>) {
  return new Promise<{ code: number | null; stderr: string }>((resolve) => {
    const env = { ...process.env };
    for (const [key, value] of Object.entries(envPatch)) {
      if (value === undefined) delete env[key];
      else env[key] = value;
    }
    execFile(process.execPath, [serverPath], { env }, (error, _stdout, stderr) => {
      const code = error ? Number(error.code) : 0;
      resolve({ code: Number.isNaN(code) ? null : code, stderr });
    });
  });
}

test("exits 1 with a clear message when KV_PORT is missing", async () => {
  const { code, stderr } = await runServer({ KV_PORT: undefined });
  assert.equal(code, 1);
  assert.match(stderr, /KV_PORT/);
});

test("exits 1 with a clear message when KV_PORT is empty", async () => {
  const { code, stderr } = await runServer({ KV_PORT: "" });
  assert.equal(code, 1);
  assert.match(stderr, /KV_PORT/);
});

test("exits 1 with a clear message when KV_PORT is not a valid port", async () => {
  const { code, stderr } = await runServer({ KV_PORT: "not-a-port" });
  assert.equal(code, 1);
  assert.match(stderr, /KV_PORT/);
});

test("starts and listens when KV_PORT is a valid port", async () => {
  const port = 8901;
  const child = execFile(
    process.execPath,
    [serverPath],
    { env: { ...process.env, KV_PORT: String(port) } },
  );
  const output = await new Promise<string>((resolve) => {
    let out = "";
    child.stdout!.on("data", (d: Buffer) => (out += d));
    child.stderr!.on("data", (d: Buffer) => (out += d));
    child.on("close", () => resolve(out));
  });
  const body = await fetch(`http://127.0.0.1:${port}/kv`).then((r) => r.text()).catch(() => "unreachable");
  child.kill();
  assert.ok(body.includes('"keys"'), `expected a list response from the live server, got: ${body}`);
  assert.match(output, /listening/);
});

