import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import { createStore, type KVStore, type PersistedStore } from "./store.ts";

/** Validate that an unknown parsed JSON value has the persisted-store shape. */
function isPersistedStore(value: unknown): value is PersistedStore {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  return Object.entries(value).every(([_, entry]) => {
    if (typeof entry !== "object" || entry === null) return false;
    const e = entry as { value?: unknown; ttlMs?: unknown };
    return typeof e.value === "string" && (e.ttlMs === null || typeof e.ttlMs === "number");
  });
}

/**
 * Load the store from `file`, creating it. Missing file means first run:
 * returns an empty store. Corrupt/unreadable file throws.
 */
export function loadStore(file: string): KVStore {
  mkdirSync(dirname(file), { recursive: true });
  const store = createStore();
  let raw: string;
  try {
    raw = readFileSync(file, "utf8");
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return store;
    throw err;
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    throw new Error(`data file ${file} is not valid JSON: ${(err as Error).message}`);
  }
  if (!isPersistedStore(parsed)) {
    throw new Error(`data file ${file} does not look like a kv store snapshot`);
  }
  store.load(parsed);
  return store;
}

/** Write the store's live entries to `file` (creating the parent directory). Expired keys are omitted. */
export function saveStore(store: KVStore, file: string): void {
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, JSON.stringify(store.serialize(), null, 2));
}
```

