import { spawn, type ChildProcess } from "node:child_process";
import { fileURLToPath } from "node:url";

export const serverPath = fileURLToPath(new URL("../src/server.ts", import.meta.url));

/** Spawn the real server with the given env vars (merged over the test env). */
export function spawnServer(env: Record<string, string>): ChildProcess {
  return spawn(process.execPath, [serverPath], {
    env: { ...process.env, ...env },
    stdio: ["ignore", "pipe", "pipe"],
  });
}

/** Resolve once the server has logged that it is listening (or fail). */
export function waitForListening(child: ChildProcess, timeoutMs = 5000): Promise<void> {
  return new Promise((resolve, reject) => {
    let out = "";
    const timer = setTimeout(
      () => reject(new Error(`server did not start in time; output: ${out}`)),
      timeoutMs,
    );
    const onData = (d: Buffer) => {
      out += d;
      if (out.includes("listening")) {
        clearTimeout(timer);
        resolve();
      }
    };
    child.stdout!.on("data", onData);
    child.stderr!.on("data", onData);
    child.on("error", (e) => {
      clearTimeout(timer);
      reject(e);
    });
    child.on("exit", (code) => {
      clearTimeout(timer);
      reject(new Error(`server exited before listening (${code}); output: ${out}`));
    });
  });
}

/** Resolve with the child's exit code once it exits. */
export function waitForExit(child: ChildProcess, timeoutMs = 5000): Promise<number | null> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error("server did not exit in time")), timeoutMs);
    child.on("exit", (code) => {
      clearTimeout(timer);
      resolve(code);
    });
  });
}

