import { test } from "node:test";
import assert from "node:assert/strict";
import {
  existsSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { loadStore, saveStore } from "../src/persist.ts";
import { createStore } from "../src/store.ts";
import { spawnServer, waitForExit, waitForListening } from "./helpers.ts";

function withTempDir(t: { after: (fn: () => void) => void }, fn: (dir: string) => void) {
  const dir = mkdtempSync(join(tmpdir(), "kv-persist-"));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  fn(dir);
}

test("saveStore writes live entries only, with remaining ttlMs", (t) => {
  withTempDir(t, (dir) => {
    let now = 0;
    const s = createStore(() => now);
    s.set("keep", "v");
    s.set("ttl", "v", 10); // expires at 10000
    s.set("gone", "v", 1); // expires at 1000
    now = 5000;
    const file = join(dir, "sub", "one.json");
    saveStore(s, file);
    const data = JSON.parse(readFileSync(file, "utf8")) as Record<
      string,
      { value: string; ttlMs: number | null }
    >;
    assert.deepEqual(Object.keys(data).sort(), ["keep", "ttl"], "expired key must be omitted");
    assert.equal(data.keep.value, "v");
    assert.equal(data.keep.ttlMs, null);
    assert.equal(data.ttl.value, "v");
    assert.equal(data.ttl.ttlMs, 5000, "remaining ttl recorded");
  });
});

test("loadStore restores values and TTLs relative to the load-time clock", (t) => {
  withTempDir(t, (dir) => {
    const file = join(dir, "two.json");
    writeFileSync(
      file,
      JSON.stringify({
        a: { value: "x", ttlMs: null },
        b: { value: "y", ttlMs: 2000 },
      }),
    );
    let now = 100;
    const s = loadStore(file);
    assert.equal(s.get("a"), "x");
    assert.equal(s.get("b"), "y");
    now = 2099;
    assert.equal(s.get("b"), "y");
    now = 2100;
    assert.equal(s.get("b"), undefined, "expired exactly at boundary");
  });
});

test("loadStore returns an empty store when the file is missing (first run)", (t) => {
  withTempDir(t, (dir) => {
    const s = loadStore(join(dir, "does-not-exist.json"));
    assert.deepEqual(s.list(), []);
  });
});

test("loadStore throws a clear error on invalid JSON", (t) => {
  withTempDir(t, (dir) => {
    const file = join(dir, "bad.json");
    writeFileSync(file, "{ not json");
    assert.throws(() => loadStore(file), /not valid JSON/);
  });
});

test("loadStore throws a clear error on wrong shape", (t) => {
  withTempDir(t, (dir) => {
    const file = join(dir, "shape.json");
    writeFileSync(file, JSON.stringify({ a: "not-an-entry" }));
    assert.throws(() => loadStore(file), /does not look like a kv store snapshot/);
  });
});

test("end-to-end: SIGTERM saves KV_DATA_FILE and a restart loads it", async (t) => {
  const dir = mkdtempSync(join(tmpdir(), "kv-persist-e2e-"));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  const file = join(dir, "nested", "kv.json"); // exercises parent-dir creation
  const port = 18902;
  const env = { KV_PORT: String(port), KV_DATA_FILE: file };

  const child = spawnServer(env);
  try {
    await waitForListening(child);
    assert.ok(
      (await fetch(`${base(port)}/kv/dur`, { method: "PUT", body: "v" })).ok,
    );
    assert.ok(
      (await fetch(`${base(port)}/kv/tmp?ttl=60`, { method: "PUT", body: "w" })).ok,
    );

    const exitCode = waitForExit(child);
    child.kill("SIGTERM");
    assert.equal(await exitCode, 0);
    assert.ok(existsSync(file), "snapshot file written on shutdown");

    const data = JSON.parse(readFileSync(file, "utf8")) as Record<
      string,
      { value: string; ttlMs: number | null }
    >;
    assert.equal(data.dur.value, "v");
    assert.equal(data.dur.ttlMs, null);
    assert.ok(
      data.tmp.ttlMs !== null && data.tmp.ttlMs > 0 && data.tmp.ttlMs <= 60000,
      `ttlMs should be within (0, 60000], got ${data.tmp.ttlMs}`,
    );
  } finally {
    child.kill("SIGKILL");
  }

  const child2 = spawnServer(env);
  try {
    await waitForListening(child2);
    const res = await fetch(`${base(port)}/kv/dur`);
    assert.equal(res.status, 200);
    assert.equal((await res.json()).value, "v");
    const res2 = await fetch(`${base(port)}/kv/tmp`);
    assert.equal(res2.status, 200, "key with remaining ttl survives restart");
  } finally {
    child2.kill("SIGKILL");
    await waitForExit(child2).catch(() => undefined);
  }
});

function base(port: number) {
  return `http://127.0.0.1:${port}`;
}

