const TOTAL_GETS = 10_000;
const CONCURRENCY = 50;
const KEYS = 1_000;
const VALUE = "x".repeat(128);

function pickKey(i: number) { return `k${i % KEYS}`; }

async function main() {
  // --- in-process server on an ephemeral port ---
  const server = createServer(createHandler(createStore()));
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  const { port } = server.address() as AddressInfo;
  const base = `http://127.0.0.1:${port}`;

  const latencies: number[] = [];
  const errors: Record<number, number> = {};

  // 50 workers pulling ops off a shared cursor
  async function runPhase(count: number, kind: "PUT" | "GET") {
    let next = 0;
