      while (true) {
        const i = next++;
        if (i >= count) return;
        const key = pickKey(i);
        const url = kind === "PUT" ? `${base}/kv/${key}` : `${base}/kv/${key}`;
        const t0 = performance.now();
        const res = await fetch(url, kind === "PUT" ? { method: "PUT", body: VALUE } : undefined);
        const body = await res.text();  // drain the response so keep-alive sockets recycle
        latencies.push(performance.now() - t0);
        if (res.status >= 400) errors[res.status] = (errors[res.status] ?? 0) + 1;
      }
    };
    await Promise.all(Array.from({ length: CONCURRENCY }, worker));
  }
