/**
 * Load test for the KV server.
 *
 * Sends 20,000 requests — 10,000 PUTs followed by 10,000 GETs — against a
 * server started in this same process, with 50 requests in flight at once.
 * The store works over a keyspace of 1,000 keys with 128-byte values, so the
 * working set stays small and the load is on the HTTP/queueing path.
 *
 * Run:
 *   npm run load
 *   node scripts/load.ts
 *
 * Prints a short report (throughput, latency percentiles, errors) and exits
 * non-zero if any request failed. Stdlib only.
 */

import { createServer } from "node:http";
import type { AddressInfo } from "node:net";
import { createHandler } from "../src/server.ts";
import { createStore } from "../src/store.ts";

const TOTAL_PUTS = 10_000;
const TOTAL_GETS = 10_000;
const CONCURRENCY = 50;
const KEYS = 1_000;
const VALUE = "x".repeat(128);

const key = (i: number) => `k${i % KEYS}`;

async function main() {
  // In-process server on an ephemeral port (no env var needed; the load
  // test imports createHandler directly, so the KV_PORT main-module guard
  // does not apply).
  const server = createServer(createHandler(createStore()));
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  const { port } = server.address() as AddressInfo;
  const base = `http://127.0.0.1:${port}`;
  console.log(`load test: ${base} (in-process), ${CONCURRENCY} in flight`);

  const latenciesMs: number[] = [];
  const failed: Record<number, number> = {};

  // A pool of `CONCURRENCY` workers pulling sequential op indices off a
  // shared cursor (safe: JS is single-threaded, next++ has no await in it).
  async function runPhase(count: number, method: "PUT" | "GET") {
    let next = 0;
    const worker = async () => {
      for (;;) {
        const i = next++;
        if (i >= count) return;
        const url = `${base}/kv/${key(i)}`;
        const t0 = performance.now();
        const res = await fetch(
          url,
          method === "PUT" ? { method: "PUT", body: VALUE } : undefined,
        );
        await res.text(); // drain so keep-alive sockets are reused
        latenciesMs.push(performance.now() - t0);
        if (res.status >= 400) failed[res.status] = (failed[res.status] ?? 0) + 1;
      }
    };
    await Promise.all(Array.from({ length: CONCURRENCY }, worker));
  }

  const wallStart = performance.now();
  await runPhase(TOTAL_PUTS, "PUT");
  const putsMs = performance.now() - wallStart;
  await runPhase(TOTAL_GETS, "GET");
  const totalMs = performance.now() - wallStart;

  const total = TOTAL_PUTS + TOTAL_GETS;
  const sorted = [...latenciesMs].sort((a, b) => a - b);
  const pct = (p: number) => sorted[Math.min(sorted.length - 1, Math.floor((p / 100) * sorted.length))];
  const nFailed = Object.values(failed).reduce((a, b) => a + b, 0);

  console.log(
    [
      `  requests      : ${total} (${TOTAL_PUTS} PUT + ${TOTAL_GETS} GET)`,
      `  wall time     : ${(totalMs / 1000).toFixed(3)} s`,
      `  throughput    : ${Math.round(total / (totalMs / 1000))} req/s`,
      `  PUT phase     : ${Math.round(TOTAL_PUTS / (putsMs / 1000))} req/s in ${(putsMs / 1000).toFixed(3)} s`,
      `  GET phase     : ${Math.round(TOTAL_GETS / ((totalMs - putsMs) / 1000))} req/s in ${((totalMs - putsMs) / 1000).toFixed(3)} s`,
      `  errors        : ${nFailed}${nFailed ? ` (${JSON.stringify(failed)})` : ""}`,
      `  latency ms    : p50 ${pct(50).toFixed(2)}  p90 ${pct(90).toFixed(2)}  p99 ${pct(99).toFixed(2)}  max ${sorted[sorted.length - 1].toFixed(2)}`,
    ].join("\n"),
  );

  server.closeAllConnections();
  await new Promise<void>((resolve, reject) =>
    server.close((err) => (err ? reject(err) : resolve())),
  );
  process.exit(nFailed ? 1 : 0);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

