import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
import { fileURLToPath } from "node:url";
import { createStore, type KVStore } from "./store.ts";
import { loadStore, saveStore } from "./persist.ts";

const MAX_VALUE_BYTES = 64 * 1024;

function json(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { "content-type": "application/json" });
  res.end(JSON.stringify(body));
}

function error(res: ServerResponse, status: number, code: string, message: string): void {
  json(res, status, { error: { code, message } });
}

async function readBody(req: IncomingMessage): Promise<string> {
  let body = "";
  for await (const chunk of req) body += chunk;
  return body;
}

export function createHandler(store: KVStore) {
  return async function handler(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const url = new URL(req.url ?? "/", `http://${req.headers.host ?? "localhost"}`);

    if (url.pathname === "/kv") {
      if (req.method !== "GET") {
        error(res, 405, "method_not_allowed", "method not allowed");
        return;
      }
      const prefix = url.searchParams.get("prefix") ?? undefined;
      json(res, 200, { keys: store.list(prefix) });
      return;
    }

    const match = url.pathname.match(/^\/kv\/([^/]+)$/);

    if (!match) {
      error(res, 404, "not_found", "not found");
      return;
    }
    const key = decodeURIComponent(match[1]);

    switch (req.method) {
      case "GET": {
        const value = store.get(key);
        if (value === undefined) {
          error(res, 404, "key_not_found", "key not found");
        } else {
          json(res, 200, { key, value });
        }
        return;
      }
      case "PUT": {
        const ttlParam = url.searchParams.get("ttl");
        let ttlSeconds: number | undefined;
        if (ttlParam !== null) {
          ttlSeconds = Number(ttlParam);
          if (!Number.isFinite(ttlSeconds) || ttlSeconds <= 0) {
            error(res, 400, "invalid_ttl", "ttl must be a positive number of seconds");
            return;
          }
        }
        const body = await readBody(req);
        if (Buffer.byteLength(body) > MAX_VALUE_BYTES) {
          error(res, 413, "value_too_large", `value must be at most ${MAX_VALUE_BYTES} bytes`);
          return;
        }
        store.set(key, body, ttlSeconds);
        json(res, 200, { ok: true, key });
        return;
      }
      case "DELETE": {
        const deleted = store.del(key);
        if (deleted) {
          json(res, 200, { ok: true, key });
        } else {
          error(res, 404, "key_not_found", "key not found");
        }
        return;
      }
      default:
        error(res, 405, "method_not_allowed", "method not allowed");
    }
  };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const rawPort = process.env.KV_PORT;
  if (rawPort === undefined || rawPort === "") {
    console.error(
      "Missing required environment variable KV_PORT.\n" +
        "Start the server with KV_PORT set to the port to listen on, e.g.:\n" +
        "  KV_PORT=<port> node src/server.ts"
    );
    process.exit(1);
  }
  const port = Number(rawPort);
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    console.error(`Invalid KV_PORT \"${rawPort}\": must be an integer between 1 and 65535.`);
    process.exit(1);
  }

  const dataFile = process.env.KV_DATA_FILE;
  let store: KVStore;
  try {
    store = dataFile !== undefined ? loadStore(dataFile) : createStore();
  } catch (err) {
    console.error(`Failed to load data file: ${(err as Error).message}`);
    process.exit(1);
  }

  const server = createServer(createHandler(store));
  server.listen(port, () => {
    console.log(`kv store listening on http://localhost:${port}`);
  });

  let shuttingDown = false;
  function shutdown(signal: string): void {
    if (shuttingDown) return;
    shuttingDown = true;
    console.log(`received ${signal}, shutting down`);
    if (dataFile !== undefined) {
      try {
        saveStore(store, dataFile);
        console.log(`store saved to ${dataFile}`);
      } catch (err) {
        console.error(`failed to save store to ${dataFile}: ${(err as Error).message}`);
        process.exit(1);
      }
    }
    server.close();
    process.exit(0);
  }
  process.on("SIGINT", () => shutdown("SIGINT"));
  process.on("SIGTERM", () => shutdown("SIGTERM"));
}

