import { test, before, after } from "node:test";
import assert from "node:assert/strict";
import { createServer, type Server } from "node:http";
import { createStore } from "../src/store.ts";
import { createHandler } from "../src/server.ts";

// Controllable clock: tests advance time without sleeping.
let now = 0;
const store = createStore(() => now);
const handler = createHandler(store);

let server: Server;
let base: string;

before(async () => {
  server = createServer(handler);
  await new Promise<void>((resolve) => server.listen(0, resolve));
  const addr = server.address();
  if (typeof addr !== "object" || addr === null) throw new Error("no address");
  base = `http://127.0.0.1:${addr.port}`;
});

after(() => server.close());

test("PUT then GET round-trips a value", async () => {
  store.del("k1");
  const put = await fetch(`${base}/kv/k1`, { method: "PUT", body: "hello" });
  assert.equal(put.status, 200);

  const res = await fetch(`${base}/kv/k1`);
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { key: "k1", value: "hello" });
});

test("PUT over 64 KiB returns 413 with error body", async () => {
  store.del("big");
  const tooBig = "a".repeat(64 * 1024 + 1);
  const res = await fetch(`${base}/kv/big`, { method: "PUT", body: tooBig });
  assert.equal(res.status, 413);
  assert.deepEqual(await res.json(), {
    error: { code: "value_too_large", message: `value must be at most ${64 * 1024} bytes` },
  });
  // rejected value is not stored
  assert.equal((await fetch(`${base}/kv/big`)).status, 404);
});

test("PUT of exactly 64 KiB is accepted", async () => {
  store.del("edge");
  const exactly = "a".repeat(64 * 1024);
  const put = await fetch(`${base}/kv/edge`, { method: "PUT", body: exactly });
  assert.equal(put.status, 200);
  const res = await fetch(`${base}/kv/edge`);
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.equal(body.value, exactly);
});

test("PUT with ttl: expired key behaves as missing", async () => {
  store.del("t1");
  const put = await fetch(`${base}/kv/t1?ttl=5`, { method: "PUT", body: "temp" });
  assert.equal(put.status, 200);

  const ok = await fetch(`${base}/kv/t1`);
  assert.equal(ok.status, 200);
  assert.deepEqual(await ok.json(), { key: "t1", value: "temp" });

  now += 5000; // exactly at expiry
  const expired = await fetch(`${base}/kv/t1`);
  assert.equal(expired.status, 404);
  assert.deepEqual(await expired.json(), {
    error: { code: "key_not_found", message: "key not found" },
  });

  // DELETE of an expired key also 404s
  const delRes = await fetch(`${base}/kv/t1`, { method: "DELETE" });
  assert.equal(delRes.status, 404);
});

test("PUT without ttl does not expire", async () => {
  store.del("t2");
  const put = await fetch(`${base}/kv/t2`, { method: "PUT", body: "stay" });
  assert.equal(put.status, 200);

  now += 10 ** 6; // a million seconds
  const res = await fetch(`${base}/kv/t2`);
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { key: "t2", value: "stay" });
});

test("PUT with invalid ttl returns 400 with error body", async () => {
  store.del("t3");
  for (const bad of ["abc", "0", "-5"]) {
    const res = await fetch(`${base}/kv/t3?ttl=${bad}`, { method: "PUT", body: "x" });
    assert.equal(res.status, 400, `ttl=${bad}`);
    assert.deepEqual(await res.json(), {
      error: { code: "invalid_ttl", message: "ttl must be a positive number of seconds" },
    });
  }
  // nothing was stored
  assert.equal((await fetch(`${base}/kv/t3`)).status, 404);
});

test("GET of missing key returns 404 with error body", async () => {
  store.del("absent");
  const res = await fetch(`${base}/kv/absent`);
  assert.equal(res.status, 404);
  assert.deepEqual(await res.json(), {
    error: { code: "key_not_found", message: "key not found" },
  });
});

test("DELETE removes a key, second DELETE is 404", async () => {
  store.del("k2");
  await fetch(`${base}/kv/k2`, { method: "PUT", body: "x" });

  const d1 = await fetch(`${base}/kv/k2`, { method: "DELETE" });
  assert.equal(d1.status, 200);

  const d2 = await fetch(`${base}/kv/k2`, { method: "DELETE" });
  assert.equal(d2.status, 404);
  assert.deepEqual(await d2.json(), {
    error: { code: "key_not_found", message: "key not found" },
  });
});

test("unknown path returns 404 with error body", async () => {
  const res = await fetch(`${base}/other`);
  assert.equal(res.status, 404);
  assert.deepEqual(await res.json(), {
    error: { code: "not_found", message: "not found" },
  });
});

test("unsupported method returns 405 with error body", async () => {
  const res = await fetch(`${base}/kv/k3`, { method: "PATCH" });
  assert.equal(res.status, 405);
  assert.deepEqual(await res.json(), {
    error: { code: "method_not_allowed", message: "method not allowed" },
  });
});

test("GET /kv lists keys; prefix filters", async () => {
  for (const k of ["list1", "list2", "other"]) store.del(k);
  await fetch(`${base}/kv/list1`, { method: "PUT", body: "a" });
  await fetch(`${base}/kv/list2`, { method: "PUT", body: "b" });
  await fetch(`${base}/kv/other`, { method: "PUT", body: "c" });

  const all = await fetch(`${base}/kv`);
  assert.equal(all.status, 200);
  const allKeys = (await all.json()).keys as string[];
  for (const k of ["list1", "list2", "other"]) {
    assert.ok(allKeys.includes(k), `missing ${k}`);
  }
  assert.ok(!allKeys.includes("t1"), "expired key should not be listed");

  const filtered = await fetch(`${base}/kv?prefix=list`);
  assert.equal(filtered.status, 200);
  assert.deepEqual((await filtered.json()).keys, ["list1", "list2"]);
});

test("GET /kv omits a key once its ttl passes", async () => {
  store.del("listexp");
  const put = await fetch(`${base}/kv/listexp?ttl=1`, { method: "PUT", body: "x" });
  assert.equal(put.status, 200);

  const present = await fetch(`${base}/kv?prefix=listexp`);
  assert.deepEqual((await present.json()).keys, ["listexp"]);

  now += 1000; // exactly at expiry
  const absent = await fetch(`${base}/kv?prefix=listexp`);
  assert.deepEqual((await absent.json()).keys, []);
});

test("non-GET on /kv returns 405 with error body", async () => {
  for (const method of ["PUT", "DELETE", "POST"] as const) {
    const res = await fetch(`${base}/kv`, {
      method,
      body: method === "PUT" ? "x" : undefined,
    });
    assert.equal(res.status, 405, method);
    assert.deepEqual(await res.json(), {
      error: { code: "method_not_allowed", message: "method not allowed" },
    });
  }
});

