import {
  closeSync,
  fsyncSync,
  mkdirSync,
  openSync,
  readFileSync,
  renameSync,
  unlinkSync,
  writeSync,
} from "node:fs";

export function saveStore(store: KVStore, file: string): void {
  mkdirSync(dirname(file), { recursive: true });
  // Atomic write: dump the snapshot to a temp file in the same directory,
  // fsync it, then rename it over the target. The rename is atomic within
  // a directory, so a crash mid-write leaves a complete old snapshot (and
  // at most a stale temp file), never a truncated one.
  const tmp = `${file}.${process.pid}.tmp`;
  try {
    const fd = openSync(tmp, "w");
    try {
      writeSync(fd, JSON.stringify(store.serialize(), null, 2));
      fsyncSync(fd);
    } finally {
      closeSync(fd);
    }
    renameSync(tmp, file);
  } catch (err) {
    try {
      unlinkSync(tmp); // best effort: remove the partial temp file
    } catch {
      // already gone (or was never created)
    }
    throw err;
  }
}

