import { test } from "node:test";
import assert from "node:assert/strict";
import {
  existsSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { loadStore, saveStore } from "../src/persist.ts";
import { createStore } from "../src/store.ts";
import { spawnServer, waitForExit, waitForListening } from "./helpers.ts";

function withTempDir(t: { after: (fn: () => void) => void }, fn: (dir: string) => void) {
  const dir = mkdtempSync(join(tmpdir(), "kv-persist-"));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  fn(dir);
}

test("saveStore writes live entries only, with remaining ttlMs", (t) => {
  withTempDir(t, (dir) => {
    let now = 0;
    const s = createStore(() => now);
    s.set("keep", "v");
    s.set("ttl", "v", 10); // expires at 10000
    s.set("gone", "v", 1); // expires at 1000
    now = 5000;
    const file = join(dir, "sub", "one.json");
    saveStore(s, file);
    const data = JSON.parse(readFileSync(file, "utf8")) as Record<
      string,
      { value: string; ttlMs: number | null }
    >;
    assert.deepEqual(Object.keys(data).sort(), ["keep", "ttl"], "expired key must be omitted");
    assert.equal(data.keep.value, "v");
    assert.equal(data.keep.ttlMs, null);
    assert.equal(data.ttl.value, "v");
    assert.equal(data.ttl.ttlMs, 5000, "remaining ttl recorded");
  });
});

test("loadStore restores values and TTLs relative to the load-time clock", (t) => {
  withTempDir(t, (dir) => {
    const file = join(dir, "two.json");
    writeFileSync(
      file,
      JSON.stringify({
        a: { value: "x", ttlMs: null },
        b: { value: "y", ttlMs: 2000 },
      }),
    );
    let now = 100;
    const s = loadStore(file, () => now);
    assert.equal(s.get("a"), "x");
    assert.equal(s.get("b"), "y");
    now = 2099;
    assert.equal(s.get("b"), "y");
    now = 2100;
    assert.equal(s.get("b"), undefined, "expired exactly at boundary");
  });
});

