test("end-to-end: SIGTERM saves KV_DATA_FILE and a restart loads it", async (t) => {
  const dir = mkdtempSync(join(tmpdir(), "kv-persist-e2e-"));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  const file = join(dir, "nested", "kv.json"); // exercises parent-dir creation
  const port = 18902;
  const env = { KV_PORT: String(port), KV_DATA_FILE: file };

  const child = spawnServer(env);
  try {
    await waitForListening(child);
    assert.ok(
      (await fetch(`${base(port)}/kv/dur`, { method: "PUT", body: "v" })).ok,
    );
    assert.ok(
      (await fetch(`${base(port)}/kv/tmp?ttl=60`, { method: "PUT", body: "w" })).ok,
    );

    const exitCode = waitForExit(child);
    child.kill("SIGTERM");
    assert.equal(await exitCode, 0);
    assert.ok(existsSync(file), "snapshot file written on shutdown");

    const data = JSON.parse(readFileSync(file, "utf8")) as Record<
      string,
      { value: string; ttlMs: number | null }
    >;
    assert.equal(data.dur.value, "v");
    assert.equal(data.dur.ttlMs, null);
    assert.ok(
      data.tmp.ttlMs !== null && data.tmp.ttlMs > 0 && data.tmp.ttlMs <= 60000,
      `ttlMs should be within (0, 60000], got ${data.tmp.ttlMs}`,
    );
  } finally {
    child.kill("SIGKILL");
  }

  const child2 = spawnServer(env);
  try {
    await waitForListening(child2);
    const res = await fetch(`${base(port)}/kv/dur`);
    assert.equal(res.status, 200);
    assert.equal((await res.json()).value, "v");
    const res2 = await fetch(`${base(port)}/kv/tmp`);
    assert.equal(res2.status, 200, "key with remaining ttl survives restart");
  } finally {
    child2.kill("SIGKILL");
    await waitForExit(child2).catch(() => undefined);
  }
});

function base(port: number) {
  return `http://127.0.0.1:${port}`;
}

