import { test } from "node:test";
import assert from "node:assert/strict";
import { spawnServer, waitForExit, waitForListening } from "./helpers.ts";

const LOG_LINE = /^\w+ \S+ \d{3} \d+(?:\.\d+)?ms$/;

async function requestCycle(port: number): Promise<void> {
  await fetch(`http://127.0.0.1:${port}/kv/a`, { method: "PUT", body: "x" });
  await fetch(`http://127.0.0.1:${port}/kv/a`);
  await fetch(`http://127.0.0.1:${port}/kv/missing`);
}

async function withServer(
  port: number,
  args: string[],
  fn: () => Promise<void>,
): Promise<string> {
  const child = spawnServer({ KV_PORT: String(port) }, args);
  let stderr = "";
  child.stderr!.on("data", (d) => (stderr += d));
  try {
    await waitForListening(child);
    await fn();
    child.kill("SIGKILL");
    await waitForExit(child);
  } finally {
    child.kill("SIGKILL");
  }
  return stderr;
}

test("each request is logged to stderr with method, path, status and duration", async () => {
  const port = 18903;
  const stderr = await withServer(port, [], () => requestCycle(port));

  const lines = stderr.split("\n").filter((l) => l.length > 0);
  assert.equal(lines.length, 3, `expected 3 log lines, got: ${stderr}`);
  for (const line of lines) {
    assert.match(line, LOG_LINE);
  }
  assert.ok(lines.some((l) => l.startsWith("PUT /kv/a 200 ")), stderr);
  assert.ok(lines.some((l) => l.startsWith("GET /kv/a 200 ")), stderr);
  assert.ok(lines.some((l) => l.startsWith("GET /kv/missing 404 ")), stderr);
});

test("--quiet disables request logging", async () => {
  const port = 18904;
  const stderr = await withServer(port, ["--quiet"], () => requestCycle(port));
  assert.equal(stderr.trim(), "");
});

