// --- Error-path robustness: every failure answers with the JSON envelope,
// and none of them take the process down. -----------------------------------

function testPort(): number {
  const addr = server.address();
  if (typeof addr !== "object" || addr === null) throw new Error("no address");
  return addr.port;
}

// Writes a raw HTTP request over a socket and resolves once the full
// response (status line + JSON body) has arrived.
function rawRequest(port: number, raw: string): Promise<string> {
  return new Promise((resolve, reject) => {
    const socket = connect({ host: "127.0.0.1", port }, () => socket.write(raw));
    let data = "";
    const timer = setTimeout(
      () => {
        socket.destroy();
        reject(new Error("raw request timed out"));
      },
      3000,
    );
    socket.on("data", (chunk: Buffer) => {
      data += chunk.toString();
      if (/HTTP\/1\.1 \d{3}[\s\S]*\}\s*$/.test(data)) {
        clearTimeout(timer);
        socket.destroy();
        resolve(data);
      }
    });
    socket.on("error", (err) => {
      clearTimeout(timer);
      reject(err);
    });
  });
}

